// 此桥不拥有内层Common事务；日历与手动付款均由同一World候选保存Common/LE/Shop/日租账。
#include "private_shop_daily_rent_integration.hpp"
#include "world_bundle.hpp"
#include "resident/domains/commerce/daily_rent/private_shop_daily_rent_player_history.hpp"
#include "resident/domains/military/military_roster_history.hpp"
#include "resident/domains/commerce/daily_rent/private_shop_daily_rent_codec.hpp"
namespace hanmo::resident {namespace {
Status available(const WorldBundle& w){if(!w.private_shop_daily_rent_enabled()||!w.private_shop_daily_rent_seed_complete||!w.private_shops_enabled()||!w.private_shops_seed_complete||!w.catalog->common||!w.catalog->local_economy)return common_failure("PrivateShopDailyRentProfileRequired");return common_success();}
bool same(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
Status player(const WorldBundle& w,const StableId& actor,const PrivateShopDailyRentCommand& command){auto guard=command_common_guard(w,actor,private_shop_daily_rent_command_kind(command));if(!guard.ok)return guard;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PrivateShopDailyRentPlayerCommandRequired");}
FamilyDeathOriginRead death_read(const WorldBundle& w,const DynamicStepInput* phase){if(!w.family_life_enabled())return {};return [&w,phase](const StableId& actor)->Outcome<std::optional<FamilyDeathOrigin>>{auto source=phase?query_military_actor_death(w.common,w.military,actor,*phase):query_military_actor_death(w.common,w.military,actor);if(!source.ok)return {false,{},source.error};if(!source.value)return {true,std::nullopt,{}};const auto& d=*source.value;return {true,FamilyDeathOrigin{d.actor_id,d.casualty_fact_id,d.battle_id,d.tick},{}};};}
PrivateShopDailyRentContext context(const PrivateShopWorldAccess& access){const auto& s=access.context();return {s,*s.daily_rent_catalog,*s.daily_rent,s.rent_executors,s.rent_death_origin};}
}
PrivateShopRentAuthorityWorldAccess::PrivateShopRentAuthorityWorldAccess(const WorldBundle& w,std::optional<TaskMessageNoticeServices> notices,const DynamicStepInput* phase)
 :world_(w),death_origin_(death_read(w,phase)),notices_(std::move(notices)){
 if(notices_){authority_.emplace(PrivateShopLiquidationContext{w.common,*w.catalog->common,w.private_shops,*w.catalog->private_shops,w.private_shop_liquidations,*w.catalog->private_shop_liquidations,*w.catalog->interaction,w.family_life,death_origin_,[this](const StableId& observer,const StableId& binding){return read_delivered_task_death_notice(world_.common,world_.tasks,*world_.catalog->tasks,*world_.catalog->common,*world_.catalog->task_message_notices,*world_.tasks.message_notices,*world_.tasks.message_handoffs,notices_->validate,observer,binding);},phase});executors_.emplace(*authority_,w.local_economy,w.private_shop_daily_rent);}
}
Outcome<std::unique_ptr<PrivateShopRentAuthorityWorldAccess>> PrivateShopRentAuthorityWorldAccess::create(const WorldBundle& w,const DynamicStepInput* phase){auto ready=available(w);if(!ready.ok)return {false,{},ready.error};if(phase&&(w.common.tick()==INT64_MAX||phase->from_tick!=w.common.tick()||phase->to_tick!=w.common.tick()+1))return {false,{},common_failure("PrivateShopRentPhaseMismatch").error};std::optional<TaskMessageNoticeServices> notices;if(w.private_shop_liquidations_enabled()){if(!w.private_shop_liquidations_seed_complete||!w.family_life_enabled()||!w.catalog->interaction||!w.catalog->tasks||!w.catalog->task_message_notices||!w.tasks.message_notices||!w.tasks.message_handoffs)return {false,{},common_failure("PrivateShopRentExecutorSourceRequired").error};auto read=make_task_message_notice_services(w,phase);if(!read.ok)return {false,{},read.error};if(!read.value)return {false,{},common_failure("PrivateShopRentExecutorSourceRequired").error};notices=std::move(*read.value);}return {true,std::unique_ptr<PrivateShopRentAuthorityWorldAccess>{new PrivateShopRentAuthorityWorldAccess(w,std::move(notices),phase)},{}};}
Status initialize_private_shop_daily_rent_world_in_candidate(WorldBundle& w){if(!w.private_shop_daily_rent_enabled())return common_success();if(w.common.tick()!=0||!w.private_shops_enabled()||!w.private_shops_seed_complete||w.private_shop_daily_rent_seed_complete||!compare_boundary(encode_private_shop_daily_rent_state(w.private_shop_daily_rent),encode_private_shop_daily_rent_state(PrivateShopDailyRentState{})).exact())return common_failure("PrivateShopRentInitialBoundaryRequired");auto shape=validate_private_shop_daily_rent_layout(w.common,nullptr);if(!shape.ok)return shape;w.private_shop_daily_rent_seed_complete=true;return common_success();}
Status validate_private_shop_daily_rent_world(const WorldBundle& w){const bool selected=w.private_shop_daily_rent_enabled();auto pair=validate_private_shop_daily_rent_pair(selected,w.catalog->identity.module_versions);if(!pair.ok)return pair;if(selected!=w.private_shop_daily_rent_seed_complete)return common_failure("PrivateShopDailyRentSeedRequired");auto shape=validate_private_shop_daily_rent_layout(w.common,selected?&w.private_shop_daily_rent:nullptr);if(!shape.ok)return shape;if(!selected){if(!compare_boundary(encode_private_shop_daily_rent_state(w.private_shop_daily_rent),encode_private_shop_daily_rent_state(PrivateShopDailyRentState{})).exact())return common_failure("UnexpectedPrivateShopDailyRentState");return validate_private_shop_daily_rent_cached_results(w.common,nullptr);}auto access=PrivateShopWorldAccess::create(w);if(!access.ok)return {false,{},access.error};auto valid=validate_private_shops(access.value->context());if(!valid.ok)return valid;valid=validate_private_shop_daily_rent_authority(context(*access.value));return valid.ok?validate_private_shop_daily_rent_cached_results(w.common,&w.private_shop_daily_rent):valid;}
Status validate_private_shop_daily_rent_player_history_world(const WorldBundle& w){return validate_private_shop_daily_rent_player_history(w.common,w.private_shop_daily_rent_enabled()?&w.private_shop_daily_rent:nullptr,[&w](Integer tick,const StableId& fact){return read_private_shop_rent_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);});}
Status reconcile_private_shop_daily_rent_world_in_candidate(WorldBundle& w,const DynamicStepInput& step){if(!w.private_shop_daily_rent_enabled())return common_success();auto ready=available(w);if(!ready.ok)return ready;return reconcile_private_shop_daily_rent_in_candidate(w.common,w.local_economy,w.private_shops,w.private_shop_daily_rent,*w.catalog->private_shop_daily_rent,step);}
Outcome<PrivateShopDailyRentQuote> prepare_private_shop_daily_rent_world(const WorldBundle& w,const StableId& actor,const PrivateShopDailyRentCommand& command){auto guard=player(w,actor,command);if(!guard.ok)return {false,{},guard.error};auto ready=available(w);if(!ready.ok)return {false,{},ready.error};auto access=PrivateShopWorldAccess::create(w);if(!access.ok)return {false,{},access.error};return preview_private_shop_daily_rent(context(*access.value),actor,command);}
Outcome<PrivateShopWorldCommit> commit_private_shop_daily_rent_world(WorldBundle& w,const StableId& actor,const PrivateShopDailyRentCommand& command,const PrivateShopDailyRentQuote& quote){auto guard=player(w,actor,command);if(!guard.ok)return {false,{},guard.error};auto ready=available(w);if(!ready.ok)return {false,{},ready.error};if(actor!=quote.actor_id||!same(quote.source_identity,w.common.state().identity)||!compare_boundary(encode_private_shop_daily_rent_command(command),encode_private_shop_daily_rent_command(quote.command)).exact())return {false,{},common_failure("StalePrivateShopDailyRent").error};auto access=PrivateShopWorldAccess::create(w);if(!access.ok)return {false,{},access.error};auto result=apply_private_shop_daily_rent_in_candidate(w.common,w.local_economy,w.private_shops,w.private_shop_daily_rent,context(*access.value),quote);if(!result.ok)return {false,{},result.error};return {true,{result.value,{}},{}};}
Outcome<BoundaryValue> query_private_shop_daily_rent_world(const WorldBundle& w,const PrivateShopDailyRentQuery& query){auto ready=available(w);if(!ready.ok)return {false,{},ready.error};auto access=PrivateShopWorldAccess::create(w);if(!access.ok)return {false,{},access.error};return query_private_shop_daily_rent(context(*access.value),w.common.state().metadata.player_actor_id,query);}
Status bind_private_shop_daily_rent_result_world(WorldBundle& w,const PrivateShopDailyRentState& before,const StableId& actor,Integer request,const CommitResult& result){if(!w.private_shop_daily_rent_enabled())return validate_private_shop_daily_rent_cached_results(w.common,nullptr);auto fresh=private_shop_daily_rent_new_command_sources(before,w.private_shop_daily_rent);if(!fresh.ok)return {false,{},fresh.error};return bind_private_shop_daily_rent_result_in_candidate(w.common,w.private_shop_daily_rent,fresh.value,actor,request,result);}
}
